// Brand marks in the Mac app (the icon sweep, 16 Oct 2026): every catalogued AI service and every app the Blocked
// window names wears its owner's mark, never letters. The images are Marks.xcassets (`mark-<id>`, an Any and a Dark
// appearance each) and the lookup tables GuardMarks.generated.swift, both GENERATED by
// packages/guard-contract/scripts/build-marks.ts (sources and licences: packages/guard-contract/marks/SOURCES.md). The
// lookups are the contract's `markForService` / `markForApp`, in the same order. An app with no sourced mark but a
// real icon on this Mac (Terminal) shows the system's own icon (NSWorkspace); anything else unknown shows a neutral
// SF Symbol — a globe, a window or a terminal.

import AppKit
import SwiftUI

enum BrandMarkContent: Equatable {
    case mark(String)
    case system(NSImage)
    case glyph(String)

    static func service(id: String?, markId: String? = nil) -> BrandMarkContent {
        if let markId, GuardMarks.titles[markId] != nil { return .mark(markId) }
        if let id, let m = GuardMarks.byService[id], GuardMarks.titles[m] != nil { return .mark(m) }
        return .glyph("globe")
    }

    static func app(_ app: String?) -> BrandMarkContent {
        guard let app, !app.isEmpty else { return .glyph("macwindow") }
        let lower = app.lowercased()
        var hits: [String?] = [GuardMarks.byBundleId[app], GuardMarks.byName[lower], GuardMarks.byCli[app]]
        for suffix in ["-cli", "_cli_rs", "_cli", "-code"] where lower.hasSuffix(suffix) {
            hits.append(GuardMarks.byCli[String(lower.dropLast(suffix.count))])
        }
        hits.append(GuardMarks.byCli[lower])
        for case let hit? in hits {
            if GuardMarks.titles[hit] != nil { return .mark(hit) }
            if let bundleId = GuardMarks.systemIconBundleId[lower] ?? (GuardMarks.byBundleId[app] == "" ? app : nil),
               let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleId) {
                return .system(NSWorkspace.shared.icon(forFile: url.path))
            }
            return .glyph("apple.terminal")
        }
        let cliLike = app.allSatisfy { $0.isLowercase || $0.isNumber || $0 == "." || $0 == "_" || $0 == "-" }
        return .glyph(cliLike ? "apple.terminal" : "macwindow")
    }
}

struct BrandMarkTile: View {
    let content: BrandMarkContent
    var size: CGFloat = 20
    @Environment(\.colorScheme) private var scheme

    private var lightTile: Bool {
        if case .mark(let id) = content { return scheme == .dark && GuardMarks.lightTileOnDark.contains(id) }
        return false
    }

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: size / 4, style: .continuous)
                .fill(lightTile ? Color(white: 0.98) : Color.primary.opacity(0.05))
            switch content {
            case .mark(let id):
                Image("mark-\(id)")
                    .resizable()
                    .scaledToFit()
                    .frame(width: size * 0.7, height: size * 0.7)
                    .environment(\.colorScheme, lightTile ? .light : scheme)
            case .system(let image):
                Image(nsImage: image).resizable().scaledToFit().frame(width: size * 0.9, height: size * 0.9)
            case .glyph(let name):
                Image(systemName: name).font(.system(size: size * 0.5)).foregroundStyle(.secondary)
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}
